package com.exelynt.booking.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="reservations",indexes={@Index(name="idx_res_user",columnList="user_id"),@Index(name="idx_res_resource",columnList="resource_id"),@Index(name="idx_res_status",columnList="status"),@Index(name="idx_res_price",columnList="price")}) public class Reservation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="resource_id") private Resource resource; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @Column(nullable=false) private LocalDateTime startTime; @Column(nullable=false) private LocalDateTime endTime; @Column(nullable=false,precision=19,scale=2) private BigDecimal price; @Enumerated(EnumType.STRING) @Column(nullable=false,length=12) private ReservationStatus status; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void create(){createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();} public Long getId(){return id;} public Resource getResource(){return resource;} public User getUser(){return user;} public LocalDateTime getStartTime(){return startTime;} public LocalDateTime getEndTime(){return endTime;} public BigDecimal getPrice(){return price;} public ReservationStatus getStatus(){return status;} public void setResource(Resource v){resource=v;} public void setUser(User v){user=v;} public void setStartTime(LocalDateTime v){startTime=v;} public void setEndTime(LocalDateTime v){endTime=v;} public void setPrice(BigDecimal v){price=v;} public void setStatus(ReservationStatus v){status=v;} }
